import { html, nothing, type PropertyValues } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Sidebar.vue as <conare-sidebar>: the console's navigation (console2.css .v2-side): 216px of paper with a hairline at
// its edge. Put a <conare-sidebar-label> over each group and a <conare-sidebar-link> per page; the `head` slot holds
// the workspace switcher (48px, over a hairline) and `foot` the account menu. It stays open on wide screens; on a
// phone the app shows it as a drawer over the page. The host is the column (a navigation landmark named by `label`,
// as Vue's <nav> is), so classes on it land on the column.

/**
 * @summary The console's navigation column.
 * @slot - Labels and links.
 * @slot head - The workspace switcher.
 * @slot foot - The account menu.
 */
export class Sidebar extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { label: {} }

	/** The navigation's name for assistive tech (main by default). */
	label?: string
	private internals = this.attachInternals()

	connectedCallback() {
		super.connectedCallback()
		this.internals.role = 'navigation'
	}
	protected willUpdate(changed: PropertyValues<this>) {
		if (changed.has('label') || !this.hasUpdated) this.internals.ariaLabel = this.label ?? 'main'
	}

	render() {
		return html`${this.hasSlot('head') ? html`<div class="h-bar shrink-0 border-b border-edge"><slot name="head"></slot></div>` : nothing}<div class="fade-y flex min-h-0 flex-1 flex-col overflow-y-auto pb-4"><slot></slot></div>${this.hasSlot('foot') ? html`<div class="shrink-0 border-t border-edge"><slot name="foot"></slot></div>` : nothing}`
	}
}

define('sidebar', Sidebar)

/* The host is the column (Sidebar.vue's <nav>), so a class on <conare-sidebar> lands on it as a class on <Sidebar>
   does. A page's own reset (Tailwind's preflight: * { border: 0 solid }) beats a host's normal styles, so the hairline
   at its edge is important. */
:host { @apply flex w-sidebar flex-col bg-surface-subtle; @apply border-r! border-edge!; }

import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// SidebarLabel.vue as <conare-sidebar-label>: a group's name in the sidebar (console2.css .v2-nav-label): 12px muted,
// 16px over it.

/**
 * @summary A group's name in the sidebar.
 * @slot - The name.
 */
export class SidebarLabel extends DsElement {
	static styles = [DsElement.styles, styles]
	render() {
		return html`<p data-ds="sidebar-label" class="px-3 pt-4 pb-1 text-meta text-fg-muted"><slot></slot></p>`
	}
}

define('sidebar-label', SidebarLabel)

import { html, nothing } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// SidebarLink.vue as <conare-sidebar-link>: one page in the sidebar (console2.css .v2-nav-link): a 28px row (44px on
// phones) with its 14px icon (an svg in the `icon` slot), the label and a count or health at the end. The page you are
// on sits on white in a hairline, in medium, with a 2px red edge at the sidebar's side. `alert` turns the count red
// when something failed.

/**
 * @summary One page in the sidebar.
 * @slot - The label.
 * @slot icon - A 14px Lucide icon.
 */
export class SidebarLink extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { href: {}, active: { type: Boolean, reflect: true }, status: {}, alert: { type: Boolean } }

	href?: string
	/** The page you are on. */
	active = false
	/** A count or health at the end. */
	status?: string
	/** The count in red: something failed. */
	alert = false

	render() {
		return html`<a data-ds="sidebar-link" href=${ifDefined(this.href)} class="ds-navlink" ?data-active=${this.active} aria-current=${ifDefined(this.active ? 'page' : undefined)}><slot name="icon"></slot><span class="min-w-0 flex-1 truncate"><slot></slot></span>${this.status ? html`<span class=${['text-meta tabular-nums', this.alert ? 'text-home-red-press' : 'text-fg-muted'].join(' ')}>${this.status}</span>` : nothing}</a>`
	}
}

define('sidebar-link', SidebarLink)

/* SidebarLink.vue's <style>. The icon is slotted from the page, so its rules reach it through ::slotted. */
.ds-navlink { position: relative; display: flex; height: var(--ds-size-control-sm); flex-shrink: 0; align-items: center; gap: var(--ds-space-md); margin: 0 8px; padding: 0 8px; color: var(--ds-color-fg-soft); font-size: var(--ds-text-ui); transition: background-color var(--ds-duration-micro) var(--ds-easing-standard), color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-navlink ::slotted(svg) { flex-shrink: 0; color: var(--ds-color-fg-muted); }
@media (hover: hover) and (pointer: fine) { .ds-navlink:hover { background: color-mix(in srgb, var(--ds-color-edge) 50%, transparent); color: var(--ds-color-fg); } }
.ds-navlink[data-active] { background: var(--ds-color-surface); color: var(--ds-color-fg); font-weight: var(--ds-font-weight-medium); outline: var(--ds-border-hairline) solid var(--ds-color-edge); outline-offset: -1px; }
.ds-navlink[data-active]::before { position: absolute; top: 6px; bottom: 6px; left: -8px; width: 2px; background: var(--ds-color-edge-accent); content: ""; }
.ds-navlink[data-active] ::slotted(svg) { color: var(--ds-color-fg); }
.ds-navlink:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-focus); outline-offset: -2px; }
@media (pointer: coarse), (max-width: 767px) { .ds-navlink { height: 44px; font-size: var(--ds-text-body); } }
